package estate.svc;

import estate.api.Context;
import estate.api.Service;
import estate.api.ServiceException;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.Map;

/** Notifier: sends marketing offers queued by the customer service. A "send" is a row in `sent`. */
public class Main implements Service {
    private Context ctx;
    private Connection db;

    @Override
    public void start(Context c) throws Exception {
        this.ctx = c;
        this.db = c.db();
        try (Statement s = db.createStatement()) {
            s.execute("CREATE TABLE IF NOT EXISTS sent(id BIGINT AUTO_INCREMENT PRIMARY KEY, customer_id VARCHAR(40) NOT NULL, "
                    + "offer_id VARCHAR(40) NOT NULL, ts BIGINT NOT NULL)");
            s.execute("CREATE TABLE IF NOT EXISTS offer_daily(customer_id VARCHAR(40) NOT NULL, platform_day BIGINT NOT NULL, "
                    + "sent_count INT NOT NULL, dropped_count BIGINT NOT NULL, PRIMARY KEY(customer_id, platform_day))");
            // Backfill state for databases created by the old version. Conflicts are
            // ignored so restarting another new instance cannot reset live counters.
            s.execute("INSERT INTO offer_daily(customer_id, platform_day, sent_count, dropped_count) "
                    + "SELECT seeded.customer_id, seeded.platform_day, seeded.sent_count, 0 "
                    + "FROM (SELECT customer_id, FLOOR(ts / 100) AS platform_day, COUNT(*) AS sent_count FROM sent "
                    + "GROUP BY customer_id, FLOOR(ts / 100)) seeded "
                    + "WHERE NOT EXISTS (SELECT 1 FROM offer_daily d WHERE d.customer_id = seeded.customer_id "
                    + "AND d.platform_day = seeded.platform_day)");
        }
    }

    @Override
    public void onEvent(String topic, Map<String, String> ev) throws Exception {
        if (!"offer.queued".equals(topic)) return;
        boolean oldAutoCommit = db.getAutoCommit();
        db.setAutoCommit(false);
        try {
            String customerId = ev.get("customerId");
            long now = ctx.now();
            long day = Math.floorDiv(now, 100);
            try (PreparedStatement init = db.prepareStatement(
                    "INSERT INTO offer_daily(customer_id, platform_day, sent_count, dropped_count) "
                            + "SELECT ?, ?, 0, 0 WHERE NOT EXISTS "
                            + "(SELECT 1 FROM offer_daily WHERE customer_id = ? AND platform_day = ?)")) {
                init.setString(1, customerId);
                init.setLong(2, day);
                init.setString(3, customerId);
                init.setLong(4, day);
                init.executeUpdate();
            }
            int updated;
            try (PreparedStatement claim = db.prepareStatement(
                    "UPDATE offer_daily SET sent_count = sent_count + 1 WHERE customer_id = ? AND platform_day = ? AND sent_count < 2")) {
                claim.setString(1, customerId);
                claim.setLong(2, day);
                updated = claim.executeUpdate();
            }
            if (updated == 1) {
                try (PreparedStatement ins = db.prepareStatement("INSERT INTO sent(customer_id, offer_id, ts) VALUES (?,?,?)")) {
                    ins.setString(1, customerId);
                    ins.setString(2, ev.get("offerId"));
                    ins.setLong(3, now);
                    ins.executeUpdate();
                }
            } else {
                try (PreparedStatement drop = db.prepareStatement(
                        "UPDATE offer_daily SET dropped_count = dropped_count + 1 WHERE customer_id = ? AND platform_day = ?")) {
                    drop.setString(1, customerId);
                    drop.setLong(2, day);
                    drop.executeUpdate();
                }
            }
            db.commit();
        } catch (Exception e) {
            db.rollback();
            throw e;
        } finally {
            db.setAutoCommit(oldAutoCommit);
        }
    }

    @Override
    public Map<String, String> handle(String op, Map<String, String> req) throws ServiceException {
        try {
            switch (op) {
                case "health": {
                    try (Statement s = db.createStatement(); ResultSet rs = s.executeQuery("SELECT COUNT(*) FROM sent")) { rs.next(); }
                    return Map.of("status", "UP");
                }
                case "sent": return sent(req);
                default: throw new ServiceException("error", "unknown op " + op);
            }
        } catch (ServiceException e) {
            throw e;
        } catch (Exception e) {
            throw new ServiceException("error", String.valueOf(e.getMessage()));
        }
    }

    /** Messages sent to a customer: count, ticks, and total offers dropped by the cap. */
    private Map<String, String> sent(Map<String, String> req) throws Exception {
        try (PreparedStatement q = db.prepareStatement("SELECT ts FROM sent WHERE customer_id = ? ORDER BY id")) {
            q.setString(1, req.get("customerId"));
            StringBuilder ticks = new StringBuilder();
            int n = 0;
            try (ResultSet rs = q.executeQuery()) {
                while (rs.next()) { if (n++ > 0) ticks.append(','); ticks.append(rs.getLong(1)); }
            }
            try (PreparedStatement d = db.prepareStatement("SELECT COALESCE(SUM(dropped_count), 0) FROM offer_daily WHERE customer_id = ?")) {
                d.setString(1, req.get("customerId"));
                try (ResultSet rs = d.executeQuery()) {
                    rs.next();
                    return Map.of("count", String.valueOf(n), "ticks", ticks.toString(), "capped", rs.getString(1));
                }
            }
        }
    }
}
