package estate.svc;

import org.junit.jupiter.api.Test;

import java.sql.Statement;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

class MainTest {
    @Test
    void queuedOfferIsSent() throws Exception {
        FakeContext c = new FakeContext();
        Main m = new Main();
        m.start(c);
        c.tick = 7;
        m.onEvent("offer.queued", Map.of("customerId", "c1", "offerId", "o1"));
        Map<String, String> r = m.handle("sent", Map.of("customerId", "c1"));
        assertEquals("1", r.get("count"));
        assertEquals("7", r.get("ticks"));
        assertEquals("0", r.get("capped"));
    }

    @Test
    void sendsAtMostTwoOffersPerCustomerPerDayAndCountsDroppedOffers() throws Exception {
        FakeContext c = new FakeContext();
        Main m = new Main();
        m.start(c);
        for (int i = 1; i <= 4; i++) {
            c.tick = i;
            m.onEvent("offer.queued", Map.of("customerId", "c1", "offerId", "o" + i));
        }
        c.tick = 100;
        m.onEvent("offer.queued", Map.of("customerId", "c1", "offerId", "o5"));

        Map<String, String> r = m.handle("sent", Map.of("customerId", "c1"));
        assertEquals("3", r.get("count"));
        assertEquals("1,2,100", r.get("ticks"));
        assertEquals("2", r.get("capped"));
    }

    @Test
    void existingSentRowsAreIncludedWhenCapStateIsCreated() throws Exception {
        FakeContext c = new FakeContext();
        try (Statement s = c.db().createStatement()) {
            s.execute("CREATE TABLE sent(id BIGINT AUTO_INCREMENT PRIMARY KEY, customer_id VARCHAR(40) NOT NULL, offer_id VARCHAR(40) NOT NULL, ts BIGINT NOT NULL)");
            s.execute("INSERT INTO sent(customer_id, offer_id, ts) VALUES ('c1', 'old1', 7), ('c1', 'old2', 8)");
        }
        Main m = new Main();
        m.start(c);
        c.tick = 9;
        m.onEvent("offer.queued", Map.of("customerId", "c1", "offerId", "new"));
        Map<String, String> r = m.handle("sent", Map.of("customerId", "c1"));
        assertEquals("2", r.get("count"));
        assertEquals("1", r.get("capped"));
    }

    @Test
    void healthIsUp() throws Exception {
        Main m = new Main();
        m.start(new FakeContext());
        assertEquals("UP", m.handle("health", Map.of()).get("status"));
    }
}
